/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.flow;

import java.time.Instant;
import java.util.Date;
import java.util.UUID;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;

import com.auth0.jwt.JWT;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.response.Response;
import jakarta.ws.rs.GET;
import jakarta.ws.rs.Path;
import jakarta.ws.rs.PathParam;
import net.civeira.phylax.feature.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/** J-04 resource API: pre-authentication and route-specific validation must agree. */
@Tag("oidc-flow")
@QuarkusTest
class ApiBearerTenantFlowTest extends OidcIntegrationTestBase {
  @Path("api/{tenant}/bearer-contract")
  public static class Resource {
    @GET
    public String get(@PathParam("tenant") String tenant) {
      return tenant;
    }
  }

  private String token(String issuer, String audience, String jti) {
    return tokenSigner.sign(OidcTestFixtures.TENANT,
        JWT.create().withIssuer(issuer).withIssuedAt(new Date()).withJWTId(jti)
            .withExpiresAt(Date.from(Instant.now().plusSeconds(300)))
            .withSubject(OidcTestFixtures.USERNAME).withAudience(audience)
            .withClaim("client_id", OidcTestFixtures.CLIENT_ID)
            .withClaim("tid", OidcTestFixtures.TENANT).withClaim("typ", "Bearer"),
        Instant.now().plusSeconds(300));
  }

  private Response api(String tenant, String token) {
    return RestAssured.given().header("Authorization", "Bearer " + token)
        .get("/api/" + tenant + "/bearer-contract");
  }

  @Test
  void rejectsWrongRouteTenantIssuerAudienceAndHotRevocation() {
    String issuer = RestAssured
        .get("/oauth/openid/" + OidcTestFixtures.TENANT + "/.well-known/openid-configuration")
        .jsonPath().getString("issuer");
    String jti = UUID.randomUUID().toString();
    String valid = token(issuer, "phylax-api", jti);
    tokenLookupGateway.storeByJti(jti, TokenIntrospectionResult.builder().active(true)
        .clientId(OidcTestFixtures.CLIENT_ID).build());
    Assertions.assertEquals(200, api(OidcTestFixtures.TENANT, valid).statusCode());
    Assertions.assertEquals(401, api(OidcTestFixtures.OTHER_TENANT, valid).statusCode());

    String foreignIssuer = token("https://foreign.example/oauth/openid/" + OidcTestFixtures.TENANT,
        "phylax-api", UUID.randomUUID().toString());
    tokenLookupGateway.storeByJti(JWT.decode(foreignIssuer).getId(), TokenIntrospectionResult
        .builder().active(true).clientId(OidcTestFixtures.CLIENT_ID).build());
    Assertions.assertEquals(401, api(OidcTestFixtures.TENANT, foreignIssuer).statusCode());
    String wrongAudience = token(issuer, "other-resource", UUID.randomUUID().toString());
    tokenLookupGateway.storeByJti(JWT.decode(wrongAudience).getId(), TokenIntrospectionResult
        .builder().active(true).clientId(OidcTestFixtures.CLIENT_ID).build());
    Assertions.assertEquals(401, api(OidcTestFixtures.TENANT, wrongAudience).statusCode());

    tokenLookupGateway.revoke(jti);
    Response revoked = api(OidcTestFixtures.TENANT, valid);
    Assertions.assertEquals(401, revoked.statusCode());
    Assertions.assertTrue(revoked.getHeader("WWW-Authenticate").startsWith("Bearer"));
  }
}
